def solve(data):
    top = data["ranking"][:data["k"]]
    relevant = set(data["relevant"])
    hits = len(set(top) & relevant)
    return {"precision": hits / len(top) if top else 0,
            "recall": hits / len(relevant) if relevant else 0}
